(r, big) => {
    const n = big ? 5000 : r.int(1, 12), hi = big ? 10000000 : 30;
    const vals = r.distinct(n, 1, hi), V = [], L = [], R = [];
    for (const v of vals) {
      V.push(v); L.push(-1); R.push(-1);
      const id = V.length - 1;
      let c = 0;
      while (id > 0) {
        if (v < V[c]) { if (L[c] < 0) { L[c] = id; break; } c = L[c]; }
        else { if (R[c] < 0) { R[c] = id; break; } c = R[c]; }
      }
    }
    const out = [], q = [0];
    for (let i = 0; i < q.length; i++) {
      const x = q[i];
      if (x < 0) { out.push(null); continue; }
      out.push(V[x]); q.push(L[x], R[x]);
    }
    while (out[out.length - 1] === null) out.pop();
    return [out, r.bool(0.7) ? r.pick(vals) : r.int(1, hi)];
  }

