class Solution:
    def subtreeAt(self, root: Optional[TreeNode], target: int) -> Optional[TreeNode]:
        if not root:
            return None
        if root.val == target:
            return root
        return self.subtreeAt(root.left, target) or self.subtreeAt(root.right, target)

